import { useCallback, useId, useMemo, useState, type KeyboardEvent } from 'react';

// Names follow the jx-* CSS-first layer in packages/core; verify against the built preset.
export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

function normalize(raw: string): string {
  return raw.trim().replace(/\s+/g, ' ');
}

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultTags = [],
  maxTags,
  onChange,
}: TagPickerProps) {
  const inputId = useId();
  const hintId = useId();
  const [tags, setTags] = useState<string[]>(defaultTags);
  const [draft, setDraft] = useState('');

  const isFull = maxTags !== undefined && tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = normalize(raw);
      if (!tag || isFull) return;
      const exists = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
      if (exists) {
        setDraft('');
        return;
      }
      commit([...tags, tag]);
      setDraft('');
    },
    [commit, isFull, tags],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((t) => t !== tag));
    },
    [commit, tags],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault();
        addTag(draft);
        return;
      }
      if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
        event.preventDefault();
        removeTag(tags[tags.length - 1]);
      }
    },
    [addTag, draft, removeTag, tags],
  );

  const hint = useMemo(() => {
    if (isFull) return `Достигнут лимит: ${maxTags}`;
    return 'Enter или запятая — добавить, Backspace — удалить последний';
  }, [isFull, maxTags]);

  return (
    <div className="jx-field jx-stack">
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <input
        id={inputId}
        className="jx-input"
        type="text"
        value={draft}
        placeholder={isFull ? '' : placeholder}
        disabled={isFull}
        aria-describedby={hintId}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />

      <p className="jx-hint" id={hintId}>
        {hint}
      </p>

      {tags.length > 0 && (
        <ul
          className="jx-cluster"
          aria-label="Выбранные теги"
          style={{ gap: 'var(--jx-space-2)' }}
        >
          {tags.map((tag) => (
            <li key={tag} className="jx-tag">
              <span className="jx-tag-label">{tag}</span>
              <button
                type="button"
                className="jx-tag-remove"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

